def unzip_app_files_new(self):
	import shutil
	import zipfile
	print 'replaced unzip app files func'
	patch_utils.LOG_CACHE_LINES = 300
	for name in patch_utils.FILES_NNED_UNZIP:
		zip_file_path = os.path.join(patch_utils.get_app_root_path(), 'res', name)
		if not os.path.isfile(zip_file_path):
			patch_log('zipfile %s not exist', zip_file_path)
			continue
		unziped_dir = os.path.join(game3d.get_doc_dir(), 'res', name.replace('.zip', ''))
		if os.path.isdir(unziped_dir) and os.listdir(unziped_dir):
			patch_log('unzip file %s obort (already unziped)', zip_file_path)
			continue
		patch_log('unzip file %s', zip_file_path)
		self.show_tips(patch_utils.gtext('首次启动，正在解压资源文件'))
		target_dir = os.path.join(game3d.get_doc_dir(), 'res')
		try:
			if not os.path.isdir(target_dir):
				os.makedirs(target_dir)
			zipf = zipfile.ZipFile(zip_file_path)
			for name in zipf.namelist():
				zipf.extract(name, target_dir)
		except:
			patch_log('unzip file %s failed', zip_file_path)
			try:
				shutil.rmtree(unziped_dir)
			except:
				pass
from patch_logic import patch_hotfix
from patch_logic import patch_mgr
patch_hotfix.replace_class_fun(patch_mgr.patch_mgr, 'unzip_app_files', unzip_app_files_new)

def patch_log_new(*args, **kwargs):
	from patch_logic import patch_utils
	if not args:
		return
	try:
		s = args[0]
		if len(args) > 1:
			s = s%args[1:]
		if patch_utils.PATCH_TYPE != patch_utils.PATCH_TYPE_PUB or patch_utils.IS_PUBTEST:
			print '===Patch== %s'%s
	except Exception as e:
		print 'patch_log_trace:',e
		traceback.print_stack()
		return
	if len(s) > 2000:
		return
	patch_utils.LOG_CACHE.append('[%s] %s\n'%(datetime.datetime.now().strftime('%H:%M:%S.%f'), s))
	if len(patch_utils.LOG_CACHE) > patch_utils.LOG_CACHE_LINES + 1000:
		patch_utils.LOG_CACHE = patch_utils.LOG_CACHE[len(patch_utils.LOG_CACHE) - patch_utils.LOG_CACHE_LINES:]
		print 'patch_log_cache_cut'
patch_hotfix.replace_class_fun(patch_utils, 'patch_log', patch_log_new)

from patch_logic import data_receiver
def make_http_tmp_dir_new():
	print 'make http tmp dir new'
	from patch_logic import patch_utils
	from patch_logic import data_receiver
	import sys
	real_dir = data_receiver.HTTP_TMP_DIR
	if not os.path.isdir(real_dir):
		patch_utils.patch_log('make_http_tmp_dir %s', real_dir)
		try:
			os.makedirs(real_dir)
		except:
			if game3d.get_platform() == game3d.PLATFORM_ANDROID and game3d.check_permission('android.permission.WRITE_EXTERNAL_STORAGE') not in (None, 1):
				game3d.request_permission('android.permission.WRITE_EXTERNAL_STORAGE', 2)
				patch_utils.alert_message_box(patch_utils.gtext("为保证游戏正常运行，请同意系统存储权限，退出后重启游戏"), ok_text = patch_utils.gtext('退出'), ok_func = lambda:game3d.exit())
			else:
				sys.excepthook(*sys.exc_info())
patch_hotfix.replace_class_fun(data_receiver, 'make_http_tmp_dir', make_http_tmp_dir_new)

